L4_1.m_Talk_THA = "ว้าว! วันนี้ฉันรู้สึกเบา ฉันอยู่ในสภาพสุดยอด!"
L4_1.m_Talk_VTN = "Ối! Hôm nay tôi cảm thấy thật nhẹ nhàng. Tôi đang ở trạng thái tốt nhất!"
L4_1.m_Talk_SCN = "呼！很好，身轻如燕。今天的状态非常棒！"
L4_1.m_Talk_DEU = "Puh! Sehr gut, meine Glieder sind leicht. Ich bin in Topform!"
L4_1.m_Talk_FRA = "Pfiou ! Je me sens si légère aujourd'hui ! Je suis en pleine forme !"
