L7_1.m_Talk_KOREA = "벌써 25번째 대결이라니, 후후, 잉그리드도 참 기운이 넘친다니까."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "もう25回目の対決だなんて。ふふっ、イングリッドって本当に元気いっぱいなんだから。"
L7_1.m_Talk_ENG = "So you guys are now at the 25th fight... Haha, Ingrid is so energetic!"
L7_1.m_Talk_TWN = "這已經是第25次的對決咧，呵呵，英格麗依舊鬥志高昂呢。"
L7_1.m_Talk_THA = "ตอนนี้พวกคุณอยู่ในไฟต์ที่ 25 แล้ว... ฮ่าๆ อิงกริดดมีพลังมาก!"
L7_1.m_Talk_VTN = "Vậy là hai người hiện đang ở trận đấu thứ 25... Haha, Ingrid thật đầy năng lượng!"
L7_1.m_Talk_SCN = "已经是第25次对决了。嘻嘻，英格丽真是充满干劲。"
L7_1.m_Talk_DEU = "Das ist schon unser 25. Duell, hoho. Ingrid, du bist wirklich voller Elan."
L7_1.m_Talk_FRA = "Tu en es donc au 25ème combat... Quelle énergie !"
