L18_1.m_Face = "UNIT_SURPRISE"
L18_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Crash = 30
L18_1.m_Talk_KOREA = "어, 어라?! 글쎄? 어쩐지 이 상황 꿈에서 본 거 같아서."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "あ、あれっ？　この状況、夢で見たような気がして。"
L18_1.m_Talk_ENG = "Huh? I don’t know. I feel like I've seen this whole thing in my dreams."
L18_1.m_Talk_TWN = "咦？！不知道？我好像夢過這個場景？"
L18_1.m_Talk_THA = "ฮะ? ฉันไม่รู้ ฉันรู้สึกเหมือนฉันได้เห็นสิ่งทั้งหมดนี้ในความฝันของฉัน"
L18_1.m_Talk_VTN = "Huh? Tôi không biết. Tôi có cảm giác như mình đã nhìn thấy toàn bộ chuyện này trong giấc mơ."
L18_1.m_Talk_SCN = "咦？！好像？这个情况在梦里见到过？"
L18_1.m_Talk_DEU = "H-huch?! Ich weiß nicht! Mir war, als hätte ich diese Szene im Traum gesehen."
L18_1.m_Talk_FRA = "Euh, c'est bizarre j'ai l'impression d'avoir déjà rêvé de ça."
