L20_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "…그래? 그럼 꿈에서 봤으니 잘 알고 있겠네."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "……そうか？　夢で見たならわかっているだろうな。"
L20_1.m_Talk_ENG = "Oh, yeah? Then you must know how it will go."
L20_1.m_Talk_TWN = "…是嗎？既然已經夢過了，那你應該知道吧。"
L20_1.m_Talk_THA = "โอ้ใช่? แล้วคุณคงรู้ว่ามันจะเป็นยังไง"
L20_1.m_Talk_VTN = "Ồ, vâng? Sau đó, cô phải biết nó sẽ diễn ra như thế nào."
L20_1.m_Talk_SCN = "……是吗？在梦里见过的话，应该很清楚吧。"
L20_1.m_Talk_DEU = "... Ach ja, dann weißt du ja bereits aus deinem Traum Bescheid."
L20_1.m_Talk_FRA = ".... Ah bon ? Dans ce cas tu dois déjà savoir comment ça va se terminer."
