L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "아무리 빨라 봤자, 그 허우적거리는 공격에 누가 맞아 주겠어?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "たとえ速度があっても、そんなやみくもな攻撃では容易に躱されてしまうぞ？"
L25_1.m_Talk_ENG = "I mean, what’s the point of being fast if you can’t hit anything?"
L25_1.m_Talk_TWN = "就算你的速度很快，但揮得毫無章法，哪個傻瓜會被你打到？"
L25_1.m_Talk_THA = "ฉันหมายถึงจะมีประโยชน์อะไรถ้าตีอะไรไม่ได้?"
L25_1.m_Talk_VTN = "Ý tôi là, nhanh để làm gì nếu không đánh trúng được thứ gì?"
L25_1.m_Talk_SCN = "就算再快，以你那虚浮的攻击，还想命中我？"
L25_1.m_Talk_DEU = "Du kannst so schnell sein, wie du willst, aber von deinen unbeholfenen Angriffen lässt sich keiner treffen."
L25_1.m_Talk_FRA = "À quoi bon être rapide si tu ne peux même pas me toucher ?"
