L43_1.m_Talk_THA = L44_1
L44_1 = "Cú sốc thua cuộc chắc hẳn đã tác động mạnh đến cô."
L43_1.m_Talk_VTN = L44_1
L44_1 = "看你胡言乱语的样子，应该是精神不太好吧？"
