L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi hiểu rồi! Cô cũng thích sôcôla bạc hà! Cô có muốn tham gia Câu lạc bộ Sô Cô La Bạc Hà không?"
L7_1.m_Talk_VTN = L8_1
