L13_1 = "라우라가 원거리에서 마법 난사만하지 않았으면 잉그리드가 이겼을지도 몰라!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ラウラが遠くから魔法を乱射さえしなければ、イングリッドが勝ってたかもだったよ！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I think you would have won if Laura didn’t throw those curses from distance!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "要不是蘿拉使出遠處亂射詛咒球，贏的說不定是你！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันคิดว่าคุณคงจะชนะถ้าลอร่าไม่โยนคำสาปพวกนั้นจากระยะไกล!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi nghĩ cô đã thắng nếu Laura không ném những lời nguyền đó từ xa!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "如果劳拉不是用远程魔法乱射，英格丽可能就赢了！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Hätte Laura dich nicht per Fernmagie zugeballert, hättest du vielleicht gewonnen!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Si Laura n'avait pas jeté ses sorts depuis aussi loin, je pense que tu aurais pu gagner !"
L12_1.m_Talk_FRA = L13_1
