L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi nhận ra trang phục của cô ấy. Đó là cô phù thủy Necronomiko."
L42_1.m_Talk_VTN = L43_1
L43_1 = "……那家伙穿的衣服，是魔法少女通灵美子吧？"
