L2_1 = "그치만 전 몸 쓰는 일은 잘 못하는 걸요. 저에게 배워도 별 도움이 안 되실 거예요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ヒミコ……体を動かすことは苦手なんです。なので、私ではお役には立てないかと……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "But I’m not good at sports. I don’t think I’ll be much help to you."
L1_1.m_Talk_ENG = L2_1
L2_1 = "可是我對運動完全不在行，找我教應該沒什麼幫助吧？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แต่ฉันเล่นกีฬาไม่เก่ง ฉันไม่คิดว่าฉันจะช่วยคุณได้มาก"
L1_1.m_Talk_THA = L2_1
L2_1 = "Nhưng tôi không giỏi thể thao. Tôi không nghĩ sẽ giúp được gì nhiều cho cô đâu."
L1_1.m_Talk_VTN = L2_1
L2_1 = "但我对运动完全不在行。向我学习对你也不会有什么帮助的。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Aber ich bin ein Körperkasper. Von mir zu lernen, wird dir wenig helfen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Les sports, c'est pas vraiment mon truc... Je ne sais pas si je vais pouvoir t'aider."
L1_1.m_Talk_FRA = L2_1
