L3_1 = "그래? 그럼 다른 사람을 찾아봐야 하나?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そうなの？　じゃあ、他をあたった方がいいのかな？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Really? Then should I find someone else?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "是嗎？那我該去找別人嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "จริงหรือ แล้วฉันควรจะหาคนอื่นมั้ย?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Thật sao? Thế thì tôi nên tìm người khác rồi?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "是吗？那我该去找别人吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ach wirklich? Soll ich jemanden anderen fragen?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Vraiment ? Peut-être que je devrais demander à quelqu'un d'autre alors."
L2_1.m_Talk_FRA = L3_1
