L4_1 = "그런데 사정을 듣자 하니, 꼭 야구를 배울 필요는 없을 것 같은데요?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ですが事情を察するに、必ず野球を学ぶ必要はなさそうですね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But you know, I don’t think baseball will solve your problem."
L3_1.m_Talk_ENG = L4_1
L4_1 = "不過我聽完你的情況，好像不是一定要學棒球？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่คุณรู้ไหม ฉันไม่คิดว่าเบสบอลจะช่วยแก้ปัญหาของคุณได้"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng, tôi không nghĩ bóng chày sẽ giải quyết được vấn đề của cô."
L3_1.m_Talk_VTN = L4_1
L4_1 = "但是听你说的情况，好像不用非要学习棒球？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aber wenn ich dir so zuhöre, glaube ich, dass es nicht unbedingt Baseball sein muss."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Mais à t'écouter, je ne sais pas si c'est vraiment le base-ball qu'il te faut."
L3_1.m_Talk_FRA = L4_1
