L7_1 = "라우라를 꺾을 수 있는 방법이 있단 말이야?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ラウラに勝てる方法があるの？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Is there another way to beat Laura?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "有其他方法可以打敗蘿拉嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "มีวิธีอื่นที่จะเอาชนะลอร่าได้หรือไม่?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Có cách nào khác để đánh bại Laura không?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "你是说有办法打败劳拉吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Gibt es einen Weg, Laura zu besiegen?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu veux dire qu'il y aurait un autre moyen de vaincre Laura ?"
L6_1.m_Talk_FRA = L7_1
