L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "저는 싸움은 좋아하지 않지만, 승부는 좋아하거든요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "はい。ヒミコ、ケンカは苦手ですが、勝負は好きなんです。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Well, I don’t like brawling, but I enjoy competition."
L7_1.m_Talk_ENG = L8_1
L8_1 = "我雖然不喜歡和人家打架，但我喜歡分勝負。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฉันไม่ชอบทะเลาะวิวาท แต่ฉันชอบการแข่งขัน"
L7_1.m_Talk_THA = L8_1
L8_1 = "Chà, tôi không thích cãi nhau, nhưng tôi thích thi đấu."
L7_1.m_Talk_VTN = L8_1
L8_1 = "我虽然不喜欢和人打架，但却喜欢决出胜负。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich mag nicht gerne kämpfen, aber Wettkämpfe mag ich schon."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je n'aime pas vraiment me battre, mais j'aime la compétition."
L7_1.m_Talk_FRA = L8_1
