L10_1.m_Pos = L11_1
L11_1 = "제가 라우라라는 분을 모르기는 하지만……"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ヒミコはラウラという方は知らないですが……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I don’t know about this Laura person..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "雖然我不認識蘿拉……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ฉันไม่รู้เกี่ยวกับลอร่าคนนี้เลย..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi không biết về người Laura này..."
