L11_1.m_Pos = L12_1
L12_1 = "사람과 사람의 사이의 승부라면 전혀 승산이 없는 건 아니에요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "PvP、つまり人間同士の勝負であれば、まったく勝算が無いわけではありません。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "But when it comes to competition, there are many paths to victory."
L11_1.m_Talk_ENG = L12_1
L12_1 = "但只要是人與人之間的勝負，就不是完全沒有勝算。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แต่เมื่อเป็นเรื่องของการแข่งขัน หนทางสู่ชัยชนะมีมากมาย"
L11_1.m_Talk_THA = L12_1
L12_1 = "Nhưng khi nói đến thi đấu, có rất nhiều con đường dẫn đến chiến thắng."
L11_1.m_Talk_VTN = L12_1
L12_1 = "但只要是人和人之间的胜负，就不是完全没有胜算。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wenn es um einen Wettkampf gegen zwei Personen gibt, hast du eine Chance."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Dans un combat, il n'y a jamais qu'une seule façon de gagner."
L11_1.m_Talk_FRA = L12_1
