L21_1 = "Are we there yet? There’s nothing here, it’s just an alley."
L20_1.m_Talk_ENG = L21_1
L21_1 = "還很遠嗎？為什麼要帶我來這麼偏僻的巷子？"
L20_1.m_Talk_TWN = L21_1
