L29_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "아무튼 저랑 이 게임을 하다보면, 승부에 대해서 감을 잡으실 수 있을 거예요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "とにかく、ヒミコとこのゲームをやれば勝負の感覚を掴むことができると思います。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Anyway, playing this game with me will help you understand how to compete."
L28_1.m_Talk_ENG = L29_1
L29_1 = "但是，在和我玩遊戲的過程中，你就可以學習到獲勝的訣竅。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อย่างไรก็ตามการเล่นเกมนี้กับฉันจะช่วยให้คุณเข้าใจวิธีการแข่งขัน"
L28_1.m_Talk_THA = L29_1
L29_1 = "Dù sao, chơi trò chơi này với tôi sẽ giúp cô hiểu cách thi đấu."
L28_1.m_Talk_VTN = L29_1
L29_1 = "但是，在和我玩游戏的过程中，你就可以学习到胜利的诀窍。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Jedenfalls wirst du dank dieses Spieles ein Gespür dafür bekommen, worum es beim Wettkampf geht."
L28_1.m_Talk_DEU = L29_1
L29_1 = "En tout cas, si tu y joues avec moi ça t'aidera à comprendre les règles de la compétition."
L28_1.m_Talk_FRA = L29_1
