L30_1 = "…으음. 좋아! 마침 주머니에 동전도 가득하거든!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "……うん、わかった！　ちょうど小銭もたくさん持ってるし！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Well, okay! I happen to have lots of coins with me anyway!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "…嗯，那好吧！反正剛好我口袋裡有很多硬幣！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "โอเค! ยังไงซะฉันก็มีเหรียญติดตัวอยู่มากมาย!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Được rồi! Dù sao thì tôi cũng có rất nhiều xu!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "……嗯，那好吧！正好兜里也有很多硬币！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "... Mhmm. Alles klar! Ich habe zufällig auch die Taschen voller Münzen!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "... Ça marche ! En plus j'ai des pièces plein les poches !"
L29_1.m_Talk_FRA = L30_1
