L36_1 = "눌렀어, 눌렀다고! 눌렀는데 왜 안 나가는 거야!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "押した、今ボタンを押したって！　どうして技が出ないのよっ！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I pressed the button! I did! Why doesn’t it work?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "我明明有按到，怎麼沒出招！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันกดปุ่มแล้ว! กดแล้ว! ทำไมมันไม่ทำงาน?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi đã nhấn nút rồi mà! Tôi đã nhấn rồi! Tại sao nó không hoạt động?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "明明按到了，按到了为什么不出招！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich habe gedrückt!!! Gedrückt habe ich! Warum wird es nicht aktiviert?!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "J'ai appuyé sur le bouton, pourtant ! Pourquoi ça marche pas ?"
L35_1.m_Talk_FRA = L36_1
