L37_1 = "是你沒按到吧？機器是不會說謊的。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่ คุณไม่ได้ทำ เครื่องจักรไม่น่าหลอก"
L36_1.m_Talk_THA = L37_1
L37_1 = "Không, cô có nhấn đâu. Máy móc không nói dối."
L36_1.m_Talk_VTN = L37_1
L37_1 = "没按到吧。机器可不会说谎哦？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Du hast halt nicht gedrückt. Maschinen lügen nicht!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Tu n'as pas du appuyer assez vite... Les machines ne se trompent jamais, tu sais ?"
