L40_1 = "솔직히 말해!! 너 지금 나 가지고 노는 거지!?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "素直に言って！　私をおちょくってるでしょ！？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Be honest! You’re toying with me, aren’t you?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "你快承認！！你根本是在耍我吧！？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ที่รัก! คุณกำลังล้อเล่นกับฉันใช่ไหม"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hãy trung thực! Cô đang đùa giỡn với tôi phải không?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "你快承认！！现在是在耍我吧！？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Sei ehrlich!!! Du führst mich an der Nase herum, oder?!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Dis-moi la vérité ! Tu te fiches de moi, c'est ça ?"
