L42_1.m_Crash = 30
L43_1 = "어떻게 한 판을 못 이길 수가 있냐고!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "なんで一戦も勝てないのよ！！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "How can I not beat you even once?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "我怎麼可能連一局都贏不了！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันจะไม่เอาชนะคุณแม้แต่ครั้งเดียวได้อย่างไร?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Sao tôi không đánh bại được cô dù chỉ một lần?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "我怎么可能连一次都赢不了呢！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wie kann ich keine einzige Runde gewinnen?!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Comment ça se fait que je n'arrive pas à te battre ? Pas une seule fois ?"
L42_1.m_Talk_FRA = L43_1
