L44_1 = "COUNTERCASE_INGRID_NORMAL_2@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 30922
L43_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_2"
