L44_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "L"
L43_1.m_Pos = L44_1
L43_1.m_Crash = 20
L44_1 = "……우으, 그치만 모르면 맞아야죠. 원래 대전 액션 게임은 맞으면서 배우는 장르예요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "……うう、でもそれがわからないなら負けるしかないです。\n元々、格闘ゲームは何度も負けながら学ぶジャンルです。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But getting beaten is the best way to learn. That’s the rule of this genre."
L43_1.m_Talk_ENG = L44_1
L44_1 = "……呃呃，你就當是在交學費吧。格鬥遊戲本來就是在不斷挨打中成長的。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แต่การพ่ายแพ้คือวิธีที่ดีที่สุดในการเรียนรู้ นั่นคือกฎของประเภทนี้"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nhưng bị đánh là cách tốt nhất để học. Đó là quy luật của thể loại này."
L43_1.m_Talk_VTN = L44_1
L44_1 = "……唔呃，你就当是在交学费吧。本来格斗游戏就是在不断挨揍中成长。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "... Oooh, aber wenn du es nicht schnallst, wirst du halt verkloppt. Kampfspiele sind ein Genre, bei dem man dazulernt, indem man verkloppt wird."
L43_1.m_Talk_DEU = L44_1
L44_1 = "En vérité... Le meilleur moyen d'apprendre à ces jeux, c'est de perdre."
