L45_1.m_Pos = "R"
L46_1 = "…아니, 그보다 그럼 그냥 곱게나 이길 것이지, 왜 자꾸 도발 버튼을 누르는 건대?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "……いや、っていうか、正々堂々と勝てばいいのに、どうして挑発コマンドばかり押すの？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Then just beat me up, already! Stop using the taunt button!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "……而且，你要贏就直接贏，為什麼每次都要按挑釁按鈕？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "งั้นก็ทุบตีฉันได้เลย! หยุดใช้ปุ่มเหน็บแนม!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Thế thì cứ đánh bại tôi đi đã! Đừng chế nhạo nữa!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "……而且，你要赢就直接赢好了。为什么每次都要按挑衅按钮呢？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "... Nein, wichtiger ist, dann gewinn halt doch fair! Warum provozierst du mich dauernd?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Dans ce cas, qu'est-ce que tu attends pour me battre ? Arrête d'utiliser le bouton de provocation !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
