L10_1 = "Thấy chưa? Cô tức giận vì lời chế nhạo vô nghĩa đó."
L9_1.m_Talk_VTN = L10_1
L10_1 = "你看，你不是因为那个毫无意义的挑衅在发火吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Siehst du? Die Provokation ist sinnlos, aber sie regt dich auf."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tu n'as toujours pas compris ? Cette provocation inutile, regarde comme elle t'énerve."
L9_1.m_Talk_FRA = L10_1
