L11_1 = "원래 상대가 흥분할수록 그 패턴이 훤히 보이는 법."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "相手が興奮すればするほど、そのパターンがはっきりとわかるんです。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "When your opponent is mad, it's easier to read them."
L10_1.m_Talk_ENG = L11_1
L11_1 = "所以對手越是心浮氣躁，就越可以看清他的攻擊套路。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เมื่อคู่ต่อสู้ของคุณโกรธ มันจะอ่านง่ายขึ้น"
L10_1.m_Talk_THA = L11_1
L11_1 = "Khi đối thủ của cô nổi điên, cô sẽ dễ dàng đọc được ý họ."
L10_1.m_Talk_VTN = L11_1
L11_1 = "所以对手越是心浮气躁，攻击就越有迹可循。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Je mehr der Gegner in Rage gerät, desto einfacher voraussehbar werden seine Verhaltensmuster."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Vois-tu... Quand ton adversaire s'énerve, il devient plus facile de lire ses mouvements."
L10_1.m_Talk_FRA = L11_1
