L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "과연 잉그리드 씨의 상대도 그렇게 생각할까요?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "イングリッドさんの相手もそう思うのでしょうか？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Would your opponent say the same?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "但你的對手也會這麼想嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ฝ่ายตรงข้ามของคุณจะพูดแบบเดียวกันหรือไม่?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đối thủ của cô có nói như vậy không?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "但英格丽的对手也会这么想吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Meinst du, dass dein Gegner auch so denkt?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Tu crois que c'est ce que se dit ton adversaire ?"
