L19_1.m_Face = L20_1
L19_1.m_CharStrID = "LAURA_STREGA_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "승부에서 비겁하다는 말은 최고의 찬사거든."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "勝負において、卑怯という言葉は最高の賛辞だ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Cowardly is the best compliment one can get in battle."
L19_1.m_Talk_ENG = L20_1
L20_1 = "在勝負的對決中說我卑鄙，是對我最好的誇獎。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ความขี้ขลาดเป็นคำชมที่ดีที่สุดที่จะได้รับในการต่อสู้"
L19_1.m_Talk_THA = L20_1
L20_1 = "Hèn nhát là lời khen tốt nhất mà ta có thể nhận được trong trận chiến."
L19_1.m_Talk_VTN = L20_1
L20_1 = "在胜负的对决中说我卑鄙，是对我最好的夸奖。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Feige genannt zu werden, ist im Kampf das größte Kompliment."
L19_1.m_Talk_DEU = L20_1
L20_1 = "« Lâche » est le meilleur des compliments que l'on peut recevoir lors d'un combat."
L19_1.m_Talk_FRA = L20_1
