L25_1 = "COUNTERCASE_INGRID_NORMAL_2@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 30922
L24_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_SURPRISE"
L24_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L24_1.m_Pos = "R"
L25_1 = "돌이켜 보면, 라우라 녀석 매번 싸울 때마다 쉴 새 없이 떠들어댔으니까."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "思い返せばラウラのやつ、戦う時には必ず私の心を揺さぶるような行動を\n取っていた。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Come to think of it, Laura talked and talked when we were in a duel."
L24_1.m_Talk_ENG = L25_1
L25_1 = "現在回想起來，蘿拉那傢伙每次決鬥時都一直在嘲諷我。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ลองคิดดูลอร่าพูดและพูดคุยเมื่อเราดวลกัน"
L24_1.m_Talk_THA = L25_1
L25_1 = "Nghĩ lại thì, Laura đã nói đi nói lại khi chúng tôi đấu tay đôi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "回想下的话，每次劳拉那个家伙，都是在不断嘲讽我。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wenn ich zurückdenke, hat Laura pausenlos geredet, wenn wir gekämpft haben."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Maintenant que j'y pense, Laura n'a pas arrêté de parler pendant qu'on se battait."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "COUNTERCASE_INGRID_NORMAL_2@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 30922
L25_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "L"
L25_1.m_Pos = L26_1
L26_1 = "그래요. <color=#ffd34c>트래시 토킹</color>도 경우에 따라 전략의 일부라고 할 수 있죠."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そうですね。場合によってはそういった<color=#ffd34c>トラッシュトーク</color>も戦略の一部と言えるでしょう。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Yes. <color=#ffd34c>Trash talk</color> can be a good tactic sometimes."
L25_1.m_Talk_ENG = L26_1
L26_1 = "是的。在某種情況下，<color=#ffd34c>垃圾話</color>也是戰略的一部分。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ใช่. <color=#ffd34c>คำพูดไร้สาระ</color>อาจเป็นกลยุทธ์ที่ดีในบางครั้ง"
L25_1.m_Talk_THA = L26_1
L26_1 = "Đúng. <color=#ffd34c>Nói xấu</color> đôi khi có thể là một chiến thuật hay."
L25_1.m_Talk_VTN = L26_1
L26_1 = "是的。在某种情况下，<color=#ffd34c>垃圾话</color>也是战略的一部分。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Genau. <color=#ffd34c>Verbale Provokation</color> ist je nach Situation ein Teil der Strategie, könnte man sagen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Oui. Le <color=#ffd34c>« Trash talk »</color> peut parfois s'avérer être une tactique efficace."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
