L26_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L26_1.m_Pos = "R"
L26_1.m_Crash = 40
L27_1 = "이제야 좀 승부에 대해서 알 것 같아!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "やっと『勝負』について理解できた気がするよ！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I think I understand now, though not perfectly!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "我好像終於找到獲勝的訣竅了！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฉันคิดว่าฉันเข้าใจแล้วแม้ว่าจะยังไม่สมบูรณ์!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi nghĩ bây giờ tôi đã hiểu, mặc dù không hoàn toàn hiểu cho lắm!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "现在我好像找到胜利的诀窍了！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich glaube, ich verstehe jetzt, worum es beim Wettkampf geht!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je crois que je comprends un peu mieux maintenant."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_INGRID_NORMAL_2@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 30922
L27_1.m_CutScenStrID = "COUNTERCASE_INGRID_NORMAL_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L27_1.m_Pos = "R"
L28_1 = "오로지 실력만이 승부를 판가름하는 건 아니다 이 말이지?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "実力だけで勝敗が決まるわけではない、ってことよね？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Skills aren't everything when you’re in a competition, right?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "並不是完全靠實力來決勝負，對吧？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ทักษะไม่ใช่ทุกอย่างเมื่อคุณอยู่ในการแข่งขันใช่ไหม?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Kỹ năng không phải là tất cả khi tham gia một cuộc thi, phải không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "并不是完全要靠实力来决出胜负，对吧？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Du willst sagen, dass es bei Sieg und Niederlage nicht nur um die Fertigkeiten geht, richtig?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Les capacités ne font pas dans un match, c'est ça ?"
L27_1.m_Talk_FRA = L28_1
