L31_1 = "좋았어! 한 판 더 해! 이번에는 꼭 내가 이길 거니까!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "よし！　あともう一回！　次は必ず勝つんだから！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Okay, let’s go for another round! And I will win this time!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "很好！那我們再來一局吧！這次我一定能贏！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "โอเค ลุยกันอีกรอบ! และครั้งนี้ฉันจะชนะ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Được rồi, chúng ta chơi thêm một hiệp nữa nhé! Và lần này tôi sẽ thắng!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "很好！那我们再来一局吧！这次我一定能赢！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Alles klar! Noch eine Runde! Dieses Mal gewinne ich!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Bien ! Refaisons une partie ! Tu vas voir, je vais gagner cette fois !"
L30_1.m_Talk_FRA = L31_1
