L42_1 = "嗯？喔喔，師父拜拜。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฮะ? เอ่อ โอเค ไปก่อน อาจารย์"
L41_1.m_Talk_THA = L42_1
L42_1 = "Huh? Ừm, được rồi, tạm biệt sư phụ"
L41_1.m_Talk_VTN = L42_1
L42_1 = "嗯？再见，师傅。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Huch! Mach‘s gut, Meisterin."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Hein ? Oh, d'accord. Au revoir, maître."
L41_1.m_Talk_FRA = L42_1
