L44_1 = "UNIT_DESPAIR"
L43_1.m_Face = L44_1
L43_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "에이… 좀 아쉽다. 뭔가 알 듯 말 듯한 기분이었는데."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "はぁ……残念だなあ。なんとなくコツが掴めてきたような気がしたのに。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I wish I had more time to learn the trick."
L43_1.m_Talk_ENG = L44_1
L44_1 = "哎…真可惜，才剛有了點頭緒說。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันหวังว่าฉันจะมีเวลามากขึ้นในการเรียนรู้เคล็ดลับ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ước gì có nhiều thời gian hơn để học trò này."
L43_1.m_Talk_VTN = L44_1
L44_1 = "哎……有些可惜呢。刚有了一点头绪。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Och ... schade. Ich war ganz nah an der Erkenntnis."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Ah, quel dommage. J'aurais bien aimé en apprendre plus."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "COUNTERCASE_INGRID_NORMAL_2@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
