L44_1.m_Face = "UNIT_IDLE"
L44_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "그래도 오늘 하루 전혀 수확이 없는 건 아니었어."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "でも、今日一日収穫がゼロってことはなかったよね。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "But still, I learned a lot today."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不過，今天一整天也不是都沒有收穫。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แต่ถึงกระนั้นฉันก็ได้เรียนรู้มากมายในวันนี้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nhưng hôm nay mình vẫn học được rất nhiều điều."
L44_1.m_Talk_VTN = L45_1
L45_1 = "不过，今天一天也不是没有收获。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Trotzdem war der Tag nicht für die Katz."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Mais cette journée n'aura pas été vaine."
L44_1.m_Talk_FRA = L45_1
