L46_1 = "…읏차! 이제 돌아가자, 그리고 다시 한번 라우라한테 도전하는 거야!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "……さて！　今日はもう帰ろう。それでラウラに再挑戦するんだ！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Let’s go back now! And I’ll challenge Laura once again!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "…嘿咻！差不多該回去了。我要再向蘿拉發起挑戰！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "กลับกันเถอะ! และฉันจะท้าทายลอร่าอีกครั้ง!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Quay lại thôi! Và mình sẽ thách thức Laura một lần nữa!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "……嘿咻！现在该回去了。然后再次向劳拉发起挑战！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "... Hepp! Jetzt gehe ich zurück. Und fordere Laura noch einmal heraus!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "... Bon ! Il est temps d'y aller. Je vais essayer de battre Laura encore une fois !"
L45_1.m_Talk_FRA = L46_1
